 * @param prtDepoId prtDepoIdSeq fileSeq
 * @returns
 * @hidden N
*/
scwin.fileDown = async function (prtDepoId, prtDepoIdSeq, fileSeq) {
    /* sdd-asis-lifecycle:begin fn_FileDown — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const downForm = (document.fileDownForm || { elements: [] });
    $c.util.getComponent('dma_FileDownReq').set('prtDepoId', prtDepoId);
    $c.util.getComponent('dma_FileDownReq').set('prtDepoIdSeq', prtDepoIdSeq);
    $c.util.getComponent('dma_FileDownReq').set('fileSeq', fileSeq);
    downForm.action = '/listInvstg/lplAttach.do';
    $c.util.getComponent('dma_FileDownReq').set('method', 'downloadPrtdepoFile');
    await scwin.tx_fn_FileDown();
    /* sdd-asis-lifecycle:end */
};


