/**
 * @method
 * @name scwin.filePrtDepoWithd
 * @author Inswave
 * @date 2026. 09. 29
 * @param type
 * @returns
 * @hidden N
*/
scwin.filePrtDepoWithd = async function (type) {
    /* sdd-asis-lifecycle:begin filePrtDepoWithd — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (type === "4") {
        var rse = await $c.win.confirm("재의무보유에 관한 첨부파일을 제출 하시겠습니까? ");
        if (rse) {
            scwin.form.action = '/listInvstg/prtDepoList.do';
            $c.util.getComponent('dma_FileDownReq').set('method', 'filePrtDepoWithd');
            { const __nr = await scwin.tx_filePrtDepoWithd(); if (__nr && __nr.responseJSON && __nr.responseJSON.success === true) { $c.win.moveUrl("/jldfil52000/jldfil52000.xml", { "method": 'filePrtDepoWithd' }); } };
        }
    } else {
        var rse = await $c.win.confirm("재의무보유에 관한 첨부파일 수정 후 제출 하시겠습니까? ");
        if (rse) {
            scwin.form.action = '/listInvstg/prtDepoList.do';
            $c.util.getComponent('dma_FileDownReq').set('method', 'updateFilePrtDepoWithd');
            { const __nr = await scwin.tx_filePrtDepoWithd(); if (__nr && __nr.responseJSON && __nr.responseJSON.success === true) { $c.win.moveUrl("/jldfil52000/jldfil52000.xml", { "method": 'filePrtDepoWithd' }); } };
        }
    }
    /* sdd-asis-lifecycle:end */
};
